{
  "name": "Handlebars Conditional Email",
  "description": "Full conditional and loop support",
  "channelCode": "EMAIL",
  "subject": "Your Account - {{accountStatus}}",
  "body": "Dear {{firstName}} {{lastName}},

{{#if isPremium}}
Thank you for being a premium member!
Your benefits include:
{{#each benefits}}
- {{this}}
{{/each}}
{{else}}
Upgrade to premium to unlock exclusive benefits!
{{/if}}

{{#if hasOrders}}
Recent Orders:
{{#each orders}}
- Order #{{this.id}}: ${{this.amount}}
{{/each}}
{{/if}}

Best regards,
The Team",
  "engineCode": "handlebars"
}

{
  "email": {
    "recipients": ["{{recipient_email}}"],
    "subject": "Test Notification from Simple Send",
    "body": "This is a test notification"
  }
}

{
  "email": {
    "recipients": ["{{recipient_email}}"],
    "subject": "Test Notification from Simple Send",
    "body": "This is a test notification",
    "delayedSend": "2026-05-03 9:10 PDT"
  }
}

{
  "email": {
    "recipients": ["{{recipient_email}}"],
    "subject": "Test Notification from Simple Send",
    "body": "This is a test notification"
  }
}
